settings.custom_liquid:
{% if collection.metafields.custom.main_banner != blank %}
  <div class="banner-section desk">
<div class="coll-banner">
<img loading="eager" src="{{ collection.metafields.custom.main_banner | img_url: 'master'}}" width="100%" >
</div>
  </div>
{% endif %}

{% if collection.metafields.custom.main_banner_mobile != blank %}
  <div class="banner-section  mob">
<div class="coll-banner">
<img loading="eager" src="{{ collection.metafields.custom.main_banner_mobile | img_url: 'master'}}" width="100%" >
</div>
  </div>
{% endif %}

<style>
  @media screen and (min-width: 1080px){
    .mob{
      display:none;
    }
  }
  @media screen and (max-width: 1079px){
    .desk{
      display:none;
    }
  }
